<template>
  <div class="drift-backdrop" @click.self="close" @keydown.esc.stop="escape" @keydown.tab="trapFocus">
    <section ref="dialog" class="run-panel journal-panel" role="dialog" aria-modal="true" aria-labelledby="drift-run-title">
      <header class="run-heading">
        <div class="heading-mark"><drift-glyph :name="state?.phase === 'exploration' ? 'compass' : 'trophy'" /></div>
        <div class="heading-copy"><small>{{ isColosseum ? 'RIFTMON / COLOSSEUM' : 'RIFTMON / EXPÉDITION RIFT' }}</small><h2 id="drift-run-title">{{ state?.phase === 'results' ? 'Bilan de l’expédition' : state?.phase === 'exploration' ? 'Carnet d’expédition' : isColosseum ? 'Le défi du Colosseum' : 'Le tournoi des survivants' }}</h2></div>
        <button ref="close" class="icon-button close-button" aria-label="Fermer le carnet Drift" @click="close"><drift-glyph name="close" /></button>
      </header>
      <template v-if="state">
        <nav class="run-tabs" role="tablist" aria-label="Carnet Drift">
          <button v-for="item in tabs" :id="`drift-tab-${item.key}`" :key="item.key" :data-drift-tab="item.key" role="tab" :aria-selected="tab === item.key" :tabindex="tab === item.key ? 0 : -1" aria-controls="drift-tab-content" @click="selectTab(item.key)" @keydown="switchTab($event, item.key)">
            <drift-glyph :name="item.icon" /><span>{{ item.label }}</span><small v-if="item.key === 'drifts'">{{ state.equipped.length }}/5</small>
          </button>
        </nav>
        <div id="drift-tab-content" ref="content" class="run-content" :class="{ 'drifts-content': tab === 'drifts', 'has-drifts': state.drifts.length, 'viewing-detail': mobileDetails }" role="tabpanel" :aria-labelledby="`drift-tab-${tab}`" tabindex="0">
          <div v-if="!state.alive && !state.report" class="outcome" :class="{ victorious: state.winnerId === userId }">
            <drift-glyph :name="state.winnerId === userId ? 'trophy' : 'compass'" />
            <div><strong>{{ state.winnerId === userId ? 'L’expédition est à toi !' : state.phase === 'results' ? 'L’expédition est terminée' : 'Ton voyage s’arrête ici' }}</strong><p>{{ outcomeReason }}</p><p>Ton équipe, tes Balls et ton butin étaient propres à cette expédition : ils ont été effacés à sa fin.</p></div>
          </div>
          <template v-if="tab === 'drifts'">
            <section class="loadout" aria-label="Drifts équipés">
              <div class="section-caption"><span>TA COMBINAISON</span><span>{{ state.equipped.length }} / {{ state.slotLimit }} équipés</span></div>
              <div class="equipped-slots">
                <button v-for="(drift, index) in equippedSlots" :key="index" :data-drift-slot="index" :class="[drift?.rarity, { filled: drift, selected: drift?.uuid === selectedId }]" :disabled="!drift" :aria-label="`Emplacement ${index + 1} : ${drift ? definition(drift).name : 'vide'}`" @click="inspect(drift)">
                  <span class="slot-number">0{{ index + 1 }}</span><drift-glyph :category="drift ? definition(drift).category : null" :rarity="drift?.rarity" /><span class="slot-name">{{ drift ? definition(drift).name : 'Libre' }}</span>
                </button>
              </div>
            </section>
            <div class="inventory-toolbar"><label class="search"><drift-glyph name="search" /><input v-model="search" class="drift-search" type="search" aria-label="Chercher dans tes Drifts" placeholder="Chercher un Drift…" @input="mobileDetails = false" /></label><span class="inventory-count">{{ state.drifts.length }} trouvés</span><span class="money"><drift-glyph name="coin" />{{ state.money }}</span></div>
            <div v-if="state.drifts.length" class="inventory-layout" :class="{ 'is-inspecting': mobileDetails }">
              <div class="owned-collection">
                <p class="section-caption">SAC DE DRIFTS <span>{{ filteredDrifts.length }} {{ filteredDrifts.length === 1 ? 'objet' : 'objets' }}</span></p>
                <div class="owned-grid">
                  <button v-for="drift in filteredDrifts" :key="drift.uuid" :data-drift-id="drift.uuid" class="owned-drift" :class="[drift.rarity, { selected: selectedDrift?.uuid === drift.uuid, equipped: state.equipped.includes(drift.uuid) }]" :aria-pressed="selectedId === drift.uuid" @click="inspect(drift)">
                    <span class="item-seal"><drift-glyph :category="definition(drift).category" :rarity="drift.rarity" /></span><span class="item-copy"><strong>{{ definition(drift).name }}</strong><small>{{ rarityName(drift.rarity) }}</small></span><span v-if="state.equipped.includes(drift.uuid)" class="equipped-tick" aria-label="Équipé">✓</span>
                  </button>
                </div>
                <p v-if="!filteredDrifts.length" class="quiet empty-search">Aucun Drift trouvé. Essaie un autre nom ou une catégorie.</p>
              </div>
              <aside v-if="selectedDrift" class="drift-detail" :class="selectedDrift.rarity" aria-labelledby="drift-detail-title">
                <button class="detail-back" data-drift-action="back" @click="backToInventory"><drift-glyph name="back" />Tous mes Drifts</button>
                <div class="detail-showcase"><span class="detail-orbit"></span><drift-glyph :category="definition(selectedDrift).category" :rarity="selectedDrift.rarity" /><span class="rarity-label">{{ rarityName(selectedDrift.rarity) }}</span></div>
                <div class="detail-copy"><small>{{ definition(selectedDrift).category }}</small><h3 id="drift-detail-title" ref="detailTitle" tabindex="-1">{{ definition(selectedDrift).name }}</h3><p>{{ definition(selectedDrift).description }}</p><div class="effect-value"><strong>{{ formatValue(definition(selectedDrift).values[selectedDrift.rarity]) }}<small>{{ definition(selectedDrift).unit }}</small></strong><span>{{ definition(selectedDrift).stat }}</span></div><p v-if="selectedDrift.element" class="element-tag">Type {{ localizedType(selectedDrift.element) }}</p><p v-if="definition(selectedDrift).rule" class="effect-rule">{{ definition(selectedDrift).rule }}</p>
                  <button class="primary equip-action" :data-drift-action="selectedEquipped ? 'unequip' : 'equip'" :disabled="!state.alive || Boolean(equipBlocked)" @click="command('drift:equip', { uuid: selectedDrift.uuid, enabled: !selectedEquipped })"><drift-glyph name="drift" />{{ selectedEquipped ? 'Retirer de ma combinaison' : 'Équiper ce Drift' }}</button>
                  <p v-if="equipBlocked" class="limit-note">{{ equipBlocked }}</p>
                  <div class="secondary-actions"><button v-if="inShop && state.phase === 'exploration'" data-drift-action="sell" :disabled="selectedEquipped || !state.alive" @click="command('drift:sell', { uuid: selectedDrift.uuid })">Vendre · {{ salePrice(selectedDrift) }} ₽</button><button data-drift-action="discard" :disabled="selectedEquipped || !state.alive" @click="askConfirmation('discard', selectedDrift)">Supprimer</button></div>
                </div>
              </aside>
            </div>
            <div v-else class="empty-inventory"><div class="empty-seal"><drift-glyph /></div><h3>Tout commence par une rencontre.</h3><p>Bats ou capture des Pokémon sauvages, ou défie des dresseurs : chaque réussite peut te rapporter un Drift. Les champions gardent les plus beaux trésors.</p><span>Cinq emplacements. À toi de choisir ta combinaison.</span></div>
          </template>
          <template v-if="tab === 'team'">
            <div class="team-intro"><div><span class="section-caption">TES COMPAGNONS</span><h3>{{ state.team.length }} Pokémon à protéger</h3></div><button v-if="state.alive" class="secondary-button" @click="$emit('team')">Fiches & ordre <span aria-hidden="true">↗</span></button></div>
            <p class="quiet team-note">Soigne tes compagnons avant de repartir : chaque K.O. est définitif.</p>
            <div class="companion-grid"><article v-for="pokemon in state.team" :key="pokemon.uuid" class="companion">
              <div class="companion-art"><pokemon-portrait :src="`${$assetBase}img/pokemon/front/${pokemon.data.id}.png`" :alt="pokemon.data.name.french || pokemon.name" /></div>
              <div class="companion-info"><div class="companion-name"><h3>{{ pokemon.data.name.french || pokemon.name }}</h3><span>N. {{ pokemon.level }}</span></div><div class="hp-label"><span>PV</span><strong>{{ pokemon.currentHp }} / {{ pokemon.maxHp }}</strong></div><div class="hp-track" :class="{ low: hpPercent(pokemon) < 30 }"><i :style="{ width: hpPercent(pokemon) + '%' }"></i></div><div v-if="state.phase === 'exploration'" class="potion-actions"><button v-for="item in potions" :key="item.key" :disabled="pokemon.currentHp >= pokemon.maxHp" @click="command('drift:heal', { pokemonUuid: pokemon.uuid, itemKey: item.key })">{{ item.name }} <small>×{{ item.quantity }}</small></button><span v-if="!potions.length" class="quiet">Plus de potions dans le sac.</span></div></div>
            </article></div>
          </template>
          <rift-participants v-if="tab === 'players'" :state="state" :user-id="userId" @watch="$emit('watch', $event)" />
          <colosseum-run v-if="isColosseum && tab === 'tournament'" :state="state" @ready="command('drift:roundReady')" />
          <template v-if="!isColosseum && tab === 'tournament'">
            <div v-if="state.phase === 'results' && state.settlement" class="account-reward" data-rift-account-reward>
              <p role="status">{{ accountSettlementText }}</p>
              <p v-if="state.settlement.reward && !state.report?.accountReward" class="reward-detail" data-rift-reward-detail>Prime du vainqueur : {{ formatValue(state.settlement.reward.coinsAwarded) }} pièces · {{ state.settlement.reward.participantCount }} dresseurs au départ · {{ rewardDuration(state.settlement.reward.explorationMs) }} d’exploration. {{ formatValue(state.settlement.reward.coinsPerPlayerMinute) }} pièces par dresseur et minute, arrondies à l’inférieur. Le tournoi ne compte pas.</p>
            </div>
            <drift-run-report v-if="state.phase === 'results' && state.report" :report="state.report" :user-id="userId" />
            <div v-if="state.phase === 'results' && !state.matches.length" class="expedition-results">
              <h3>Fin pendant l’exploration</h3><p class="quiet">Il ne reste plus assez de dresseurs pour organiser le tournoi.</p>
              <ul><li v-for="player in state.players" :key="player.id"><span>{{ player.username }}<small v-if="player.id === userId"> · Toi</small></span><strong>{{ player.id === state.winnerId ? 'Vainqueur' : eliminationLabel(player.reason) }}</strong></li></ul>
            </div>
            <div v-else-if="!state.matches.length" class="empty-inventory tournament-empty"><div class="empty-seal"><drift-glyph name="trophy" /></div><h3>Le rendez-vous des survivants</h3><p>À la fin du chrono, rejoins l’arène avec ton équipe. Le tableau des duels apparaîtra ici.</p><span>Élimination simple · Soins entre les rounds</span></div>
            <template v-else>
              <p v-if="hasBye" class="bye-notice" data-rift-bye>Le tirage au sort t’accorde une exemption pour ce round. Tu passes au suivant et peux regarder un duel pendant ton attente.</p>
              <div class="tournament-intro"><div><span class="section-caption">ÉLIMINATION SIMPLE</span><h3>{{ state.phase === 'results' ? 'Le tableau final' : roundName(state.currentRound) }}</h3><p class="quiet">Les pertes sont définitives. Les survivants sont soignés entre les rounds.</p></div><button v-if="canReady" class="primary" data-drift-action="ready" :disabled="state.ready" @click="command('drift:roundReady')"><drift-glyph name="trophy" />{{ state.ready ? 'Prêt · en attente' : 'Prendre ma place' }}</button></div>
              <div class="bracket" tabindex="0" role="region" aria-label="Tableau des duels, défilement horizontal"><section v-for="round in rounds" :key="round" class="bracket-round"><h4><span>0{{ round }}</span>{{ roundName(round) }}</h4><div class="round-matches"><article v-for="match in state.matches.filter(m => m.round === round)" :key="match.id" class="match" :class="{ 'my-match': match.players.includes(userId), 'match-active': match.status === 'battle' }"><small class="match-status"><i></i>{{ { waiting: 'Préparation', battle: 'En combat', finished: 'Terminé', bye: 'Exemption' }[match.status] }}</small><div v-for="(id,index) in match.players" :key="index" class="match-player" :class="{ winner: id && match.winnerId === id, 'is-me': id === userId }"><span class="player-mark"><drift-glyph :name="id && match.winnerId === id ? 'trophy' : 'team'" /></span><span>{{ id ? playerName(id) : 'Exemption' }}<small v-if="id === userId">TOI</small></span><b v-if="id && match.winnerId === id" aria-label="Vainqueur">✓</b></div><button v-if="canWatch(match)" class="watch-match" :data-spectate-match="match.id" @click="$emit('watch', match.id)"><drift-glyph name="players" />Regarder ce duel</button></article></div></section></div>
            </template>
          </template>
        </div>
        <footer class="run-footer"><span class="footer-status" role="status">{{ feedback || (inShop && tab === 'drifts' ? 'Boutique · Tu peux revendre tes Drifts non équipés.' : state.alive ? 'Une expédition. Une seule vie.' : 'Une nouvelle expédition t’attend.') }}</span><button v-if="state.alive" class="leave-button" @click="askConfirmation('abandon')">Abandonner</button><button v-else class="secondary-button" data-drift-action="exit" @click="$emit('leave')">{{ isColosseum ? 'Retour au classement' : 'Retour au salon' }} <span aria-hidden="true">→</span></button></footer>
        <div v-if="confirmation" class="confirmation-backdrop" @click.self="cancelConfirmation"><section ref="confirm" class="confirm" role="alertdialog" aria-modal="true" aria-labelledby="drift-confirm-title" aria-describedby="drift-confirm-copy"><drift-glyph :name="confirmation === 'discard' ? 'drift' : 'compass'" /><h3 id="drift-confirm-title">{{ confirmation === 'discard' ? 'Se séparer de ce Drift ?' : 'Quitter l’expédition ?' }}</h3><p id="drift-confirm-copy">{{ confirmation === 'discard' ? `${definition(discardTarget).name} disparaîtra de ton sac. Tu peux aussi le revendre en boutique pour ${salePrice(discardTarget)} ₽.` : 'Ton équipe, tes Drifts et ton butin seront perdus.' }}</p><div><button class="secondary-button" data-drift-action="cancel" @click="cancelConfirmation">{{ confirmation === 'discard' ? 'Conserver' : 'Continuer' }}</button><button class="danger-button" data-drift-action="confirm" @click="confirmAction">{{ confirmation === 'discard' ? 'Supprimer' : 'Abandonner' }}</button></div></section></div>
      </template>
      <p v-else class="loading-state">Ouverture de ton carnet…</p>
    </section>
  </div>
</template>

<script>
import { getSession } from '@/services/session';
import DriftGlyph from './DriftGlyph.vue';
import DriftRunReport from './DriftRunReport.vue';
import ColosseumRun from './ColosseumRun.vue';
import RiftParticipants from './RiftParticipants.vue';
import PokemonPortrait from '../PokemonPortrait.vue';

export default {
  name: 'DriftRunPanel',
  components: { DriftGlyph, DriftRunReport, ColosseumRun, RiftParticipants, PokemonPortrait },
  props: { state: Object, catalogue: Object, inShop: Boolean, feedback: { type: String, default: '' } },
  data() {
    return { tab: this.state?.phase === 'exploration' ? 'drifts' : 'tournament', search: '', selectedId: null, mobileDetails: false,
      confirmation: null, discardTarget: null, previousFocus: null, confirmationFocus: null, userId: Number(getSession()?.id),
      prices: { common: 50, rare: 120, epic: 300, legendary: 800, mythic: 2000 } };
  },
  computed: {
    isColosseum() { return this.state?.mode === 'colosseum'; },
    accountSettlementText() {
      const settlement = this.state?.settlement;
      if (settlement?.status !== 'complete') return this.state?.winnerId === this.userId ? 'Ta victoire est en cours d’enregistrement. La prime attend confirmation.' : 'Ton résultat est en cours d’enregistrement sur ton compte RiftMon…';
      if (this.state.winnerId !== this.userId) return 'Ton résultat a été enregistré sur ton compte RiftMon.';
      if (settlement.coinsAwarded == null || !Number.isFinite(Number(settlement.coinsAwarded))) return 'Ta victoire a été enregistrée sur ton compte RiftMon.';
      return `${this.formatValue(settlement.coinsAwarded)} pièces RiftMon ajoutées à ton compte.`;
    },
    tabs() { if (this.isColosseum) return this.state.phase === 'results' ? [{key:'tournament',label:'Bilan du défi',icon:'trophy'}] : [{key:'drifts',label:'Drifts',icon:'drift'},{key:'team',label:'Équipe',icon:'team'},{key:'tournament',label:'Colosseum',icon:'trophy'}]; return this.state?.phase === 'results' && this.state.report ? [{ key: 'tournament', label: 'Bilan & tableau final', icon: 'trophy' }] : [{ key: 'drifts', label: 'Drifts', icon: 'drift' }, { key: 'team', label: 'Équipe', icon: 'team' }, { key: 'players', label: 'Survivants', icon: 'players' }, { key: 'tournament', label: 'Tournoi', icon: 'trophy' }]; },
    hasBye() { return this.state?.alive && this.state.matches.some(match => match.round === this.state.currentRound && match.status === 'bye' && match.players.includes(this.userId)); },
    outcomeReason() {
      if (this.state?.winnerId === this.userId) return 'Tu es le dernier dresseur en lice. L’expédition est terminée, même si le chrono n’était pas écoulé.';
      return {
        disconnected: 'Ta connexion n’a pas été rétablie dans les 90 secondes : tu as été déclaré forfait.',
        forfeit: 'Tu as abandonné cette expédition.',
        defeated: 'Tous tes Pokémon ont été mis K.O. : tu es éliminé.',
        not_ready: 'Tu n’étais pas prêt à la fin du délai de préparation : tu es éliminé.'
      }[this.state?.reason] || 'Tu ne participes plus à cette expédition.';
    },
    filteredDrifts() { const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); const q = normalize(this.search); return (this.state?.drifts || []).filter(d => normalize(`${this.definition(d).name} ${this.definition(d).category}`).includes(q)); },
    selectedDrift() { return this.state?.drifts.find(d => d.uuid === this.selectedId) || this.filteredDrifts[0] || null; },
    selectedEquipped() { return Boolean(this.selectedDrift && this.state.equipped.includes(this.selectedDrift.uuid)); },
    equippedSlots() { return Array.from({ length: this.state?.slotLimit || 5 }, (_, index) => this.state.drifts.find(d => d.uuid === this.state.equipped[index]) || null); },
    equipBlocked() {
      if (!this.selectedDrift || this.selectedEquipped) return '';
      if (this.state.equipped.length >= this.state.slotLimit) return 'Tes cinq emplacements sont occupés. Retire un Drift pour en changer.';
      return this.state.drifts.some(d => d.definitionId === this.selectedDrift.definitionId && this.state.equipped.includes(d.uuid)) ? 'Un Drift de cette famille est déjà équipé.' : '';
    },
    potions() { return (this.state?.items || []).filter(i => i.category === 'heal' && i.quantity > 0); },
    rounds() { return [...new Set(this.state?.matches.map(m => m.round) || [])]; },
    canReady() { return this.state?.alive && this.state.matches.some(m => m.round === this.state.currentRound && m.status === 'waiting' && m.players.includes(this.userId)); }
  },
  watch: {
    'state.phase'(phase) { if (phase !== 'exploration') this.selectTab('tournament'); },
    'state.alive'(alive) { if (!alive) this.confirmation = null; },
    'state.drifts'() { if (this.selectedId && !this.state.drifts.some(d => d.uuid === this.selectedId)) { this.selectedId = null; this.mobileDetails = false; } }
  },
  mounted() { this.previousFocus = document.activeElement; this.$refs.close.focus(); },
  beforeDestroy() { if (this.previousFocus?.isConnected) this.previousFocus.focus(); },
  methods: {
    rewardDuration(ms) { const seconds = Math.max(0, Math.floor((Number(ms) || 0) / 1000)); return `${Math.floor(seconds / 60)} min ${String(seconds % 60).padStart(2, '0')} s`; },
    canWatch(match) { return this.state?.spectatingAvailable && !this.state.ready && match.status === 'battle' && !match.players.includes(this.userId); },
    definition(d) { return this.catalogue?.definitions.find(item => item.id === d?.definitionId) || { name: d?.definitionId || 'Drift', category: '', values: {} }; },
    rarityName(key) { return this.catalogue?.rarities.find(r => r.key === key)?.name || key; },
    playerName(id) { return this.state.players.find(p => p.id === id)?.username || 'Dresseur'; },
    eliminationLabel(reason) { return { disconnected: 'Déconnexion · forfait', forfeit: 'Abandon', defeated: 'Équipe K.O.', not_ready: 'Non prêt · forfait', finished: 'Terminé' }[reason] || 'Éliminé'; },
    localizedType(type) { return { Normal: 'Normal', Fire: 'Feu', Water: 'Eau', Electric: 'Électrik', Grass: 'Plante', Ice: 'Glace', Fighting: 'Combat', Poison: 'Poison', Ground: 'Sol', Flying: 'Vol', Psychic: 'Psy', Bug: 'Insecte', Rock: 'Roche', Ghost: 'Spectre', Dragon: 'Dragon', Dark: 'Ténèbres', Steel: 'Acier', Fairy: 'Fée' }[type] || type; },
    salePrice(drift) { const merchant = this.state.drifts.find(d => d.definitionId === 'DRF-053' && this.state.equipped.includes(d.uuid)); return Math.floor(this.prices[drift.rarity] * (1 + (merchant ? this.definition(merchant).values[merchant.rarity] / 100 : 0))); },
    formatValue(value) { return Number(value || 0).toLocaleString('fr-FR'); },
    hpPercent(pokemon) { return Math.max(0, Math.min(100, pokemon.currentHp / pokemon.maxHp * 100)); },
    roundName(round) { const size = this.state.matches.filter(m => m.round === round).length; return size === 1 ? 'Finale' : size === 2 ? 'Demi-finales' : size === 4 ? 'Quarts de finale' : `Round ${round}`; },
    command(name, data = {}) { this.$emit('command', { name, data }); },
    close() { if (this.confirmation) this.cancelConfirmation(); else this.$emit('close'); },
    escape(event) { event.preventDefault(); if (this.confirmation) this.cancelConfirmation(); else if (this.mobileDetails && window.matchMedia('(max-width: 600px)').matches) this.backToInventory(); else this.close(); },
    inspect(drift) { this.selectedId = drift.uuid; this.mobileDetails = true; this.$nextTick(() => { if (window.matchMedia('(max-width: 600px)').matches) { this.$refs.detailTitle?.focus({ preventScroll: true }); this.$refs.content.scrollTop = 0; } }); },
    backToInventory() { this.mobileDetails = false; this.$nextTick(() => this.$el.querySelector(`[data-drift-id="${this.selectedId}"]`)?.focus()); },
    selectTab(key) { this.tab = key; this.mobileDetails = false; this.$nextTick(() => { if (this.$refs.content) this.$refs.content.scrollTop = 0; }); },
    switchTab(event, key) {
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault(); const index = this.tabs.findIndex(t => t.key === key);
      const count = this.tabs.length;
      const target = event.key === 'Home' ? 0 : event.key === 'End' ? count - 1 : (index + (event.key === 'ArrowRight' ? 1 : count - 1)) % count;
      this.selectTab(this.tabs[target].key); this.$nextTick(() => this.$el.querySelector(`[data-drift-tab="${this.tab}"]`).focus());
    },
    askConfirmation(kind, drift = null) { this.confirmationFocus = document.activeElement; this.confirmation = kind; this.discardTarget = drift; this.$nextTick(() => this.$refs.confirm.querySelector('[data-drift-action="cancel"]').focus()); },
    cancelConfirmation() { this.confirmation = null; this.$nextTick(() => { if (this.confirmationFocus?.isConnected) this.confirmationFocus.focus(); }); },
    confirmAction() { if (this.confirmation === 'discard') this.command('drift:discard', { uuid: this.discardTarget.uuid }); else this.command('drift:abandon'); this.cancelConfirmation(); },
    trapFocus(event) {
      const root = this.confirmation ? this.$refs.confirm : this.$refs.dialog;
      const elements = [...root.querySelectorAll('button:not(:disabled), input, summary, a[href], [tabindex="0"]')].filter(el => el.getClientRects().length && el.getAttribute('tabindex') !== '-1');
      const first = elements[0], last = elements[elements.length - 1];
      if (event.shiftKey && (document.activeElement === first || !root.contains(document.activeElement))) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && (document.activeElement === last || !root.contains(document.activeElement))) { event.preventDefault(); first?.focus(); }
    }
  }
};
</script>

